# Terraform: ALB with path-based routing to two target groups
# This illustrates the compute + networking integration clearly

resource "aws_lb" "app" {
  name               = "app-alb"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]  # must span >= 2 AZs
  enable_deletion_protection = true
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.app.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.cert.arn

  # Default action: forward to frontend target group
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.frontend.arn
  }
}

# Route /api/* to the backend service
resource "aws_lb_listener_rule" "api" {
  listener_arn = aws_lb_listener.https.arn
  priority     = 100

  condition {
    path_pattern { values = ["/api/*"] }
  }

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.backend.arn
  }
}

# Backend target group with health check
resource "aws_lb_target_group" "backend" {
  name        = "backend-tg"
  port        = 3000
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"  # for containers; use 'instance' for EC2

  health_check {
    path                = "/health"
    healthy_threshold   = 2      # 2 consecutive successes → healthy
    unhealthy_threshold = 2      # 2 consecutive failures  → unhealthy
    interval            = 30     # check every 30 seconds
    timeout             = 5      # expect response within 5s
    matcher             = "200"  # only 200 OK is healthy
  }
}
